use genewars_runtime::{creature_world::*,actor_activation::TrigTables,physics_tables::PhysicsTables};
use std::{fs,path::PathBuf};
fn main(){let p=PathBuf::from(std::env::args().nth(1).unwrap());let physics=PhysicsTables::from_mapped_bytes(&fs::read(p.join("angles.bin")).unwrap(),&fs::read(p.join("bounce.bin")).unwrap()).unwrap().with_corpse_friction(&fs::read(p.join("corpse-friction.bin")).unwrap()).unwrap();let trig=TrigTables::generate_pinned().unwrap();let animations=MuleAnimations::from_anb(&fs::read(p.join("mule.anb")).unwrap()).unwrap().with_bones_anb(&fs::read(p.join("bones.anb")).unwrap()).unwrap();let maps=[fs::read(p.join("map.bin")).unwrap(),fs::read(p.join("map-seed65535.bin")).unwrap()];let input=fs::read(p.join("input.bin")).unwrap();assert_eq!(input.len(),114*128);let mut actual=Vec::new();let mut checks=0;
 for(index,row)in input.chunks_exact(128).enumerate(){let frame=u32::from_le_bytes(row[..4].try_into().unwrap());let before:[u8;124]=row[4..].try_into().unwrap();let map=&maps[usize::from(index==1)];let prefix=plan_common_straight_motion_prefix(&before,frame,&physics,&trig,true,true,true).unwrap();let context=MuleStepContext{frame_counter:frame,gravity:1024,water_height:1632,climate:106};
  let got=plan_mule_bones_retirement_after_prefix(&before,&prefix,map,context,&physics,&trig,&animations).unwrap_or_else(|e|panic!("case{index}:{e:?}"));assert!(got.retirement_required);assert_eq!(got.motion.after[6],1);assert_eq!(&got.motion.after[..6],&before[..6]);assert_eq!(&got.motion.after[31..39],&before[31..39]);actual.extend_from_slice(&got.motion.after);checks+=4;
  assert!(plan_mule_bones_retirement_after_prefix(&before,&prefix,map,MuleStepContext{frame_counter:frame+1,..context},&physics,&trig,&animations).is_err());checks+=1;
  let target=[i16::from_le_bytes(prefix[11..13].try_into().unwrap()),i16::from_le_bytes(prefix[13..15].try_into().unwrap())];assert!(plan_mule_after_admitted_prefix_with_water_policy(&before,&prefix,target,map,context,&physics,&trig,|_,_,_|panic!("A4 mustskip"),|_|Ok(false),&animations,|_|Err(CreatureError::UnsupportedMotionState),true).is_err());checks+=1;
 }fs::write(p.join("actual.bin"),actual).unwrap();println!("114 retirement plans; {checks} checks");}
